struct Cache<Value> {
    var items: [String: Value] = [:]
}
var images = Cache<String>()
images.items["a"] = "a.png"

// T is the type parameter.
func flip<T>(_ a: inout T, _ b: inout T) {
    let temp = a
    a = b
    b = temp
}

func same<T: Equatable>(
    _ a: T, _ b: T
) -> Bool {
    a == b
}
print(same(1, 1))
